func fuzz<T>(items: [T], triples: [(T, T, T)], value: Optional<T>, pair: (T, T)) {
switch value { case .import(_, let s): break default: break }
switch value { case .import(_, let s): break default: break }
for var item in items { _ = item }
guard case .some(let x) = value else { return }
}
